<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
  <meta name="color-scheme" content="dark">
  <title>Vegan ramen</title>
  <style>
    *, *::before, *::after { box-sizing: border-box; }
    html, body { width: 100%; height: 100%; margin: 0; overflow: hidden; }
    body { background: #100d0c; }
    .scene { position: relative; width: 100%; height: 100%; overflow: hidden; isolation: isolate; }
    canvas { display: block; pointer-events: none; }
    .table { position: absolute; inset: 0; width: 100%; height: 100%; }
    .dish, .steam { position: absolute; }
    .dish canvas { position: absolute; inset: 0; width: 100%; height: 100%; }
  </style>
</head>
<body>
  <main class="scene" role="img" aria-label="Steam curling over a dark ceramic bowl of ramen with golden tofu, shiitake mushrooms and bok choy">
    <canvas class="table" aria-hidden="true"></canvas>
    <div class="dish" aria-hidden="true">
      <canvas class="ceramic"></canvas>
      <canvas class="reflections"></canvas>
      <canvas class="toppings"></canvas>
    </div>
    <canvas class="steam" aria-hidden="true"></canvas>
  </main>
  <script>
    (() => {
      'use strict';

      const scene = document.querySelector('.scene');
      const table = document.querySelector('.table');
      const dish = document.querySelector('.dish');
      const ceramic = document.querySelector('.ceramic');
      const reflections = document.querySelector('.reflections');
      const toppings = document.querySelector('.toppings');
      const steam = document.querySelector('.steam');
      const motion = matchMedia('(prefers-reduced-motion: reduce)');

      const tau = 2 * Math.PI;
      const origin = { x: 550, y: 434 };
      const art = { x: 132, y: 265, width: 836, height: 453 };
      const vapor = { x: 164, bottom: 502, width: 772, height: 485 };
      const liquid = { x: 550, y: 438, rx: 370, ry: 132 };
      const clamp = (v, min = 0, max = 1) => Math.max(min, Math.min(max, v));
      const mix = (a, b, t) => a + (b - a) * t;
      const smooth = (a, b, v) => {
        const t = clamp((v - a) / (b - a));
        return t * t * (3 - 2 * t);
      };

      function random(seed) {
        return () => {
          seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
          return seed / 4294967296;
        };
      }

      function hash(x, y) {
        let h = Math.imul(x, 374761393) + Math.imul(y, 668265263);
        h = Math.imul(h ^ (h >>> 13), 1274126177);
        return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
      }

      function noise(x, y) {
        const i = Math.floor(x);
        const j = Math.floor(y);
        let u = x - i;
        let v = y - j;
        u *= u * (3 - 2 * u);
        v *= v * (3 - 2 * v);
        return mix(mix(hash(i, j), hash(i + 1, j), u),
          mix(hash(i, j + 1), hash(i + 1, j + 1), u), v);
      }

      function linear(ctx, x0, y0, x1, y1, stops) {
        const gradient = ctx.createLinearGradient(x0, y0, x1, y1);
        for (const [offset, color] of stops) gradient.addColorStop(offset, color);
        return gradient;
      }

      function oval(x, y, rx, ry, angle = 0) {
        const path = new Path2D();
        path.ellipse(x, y, rx, ry, angle, 0, tau);
        return path;
      }

      function blot(ctx, x, y, rx, ry, stops, angle = 0) {
        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(angle);
        ctx.scale(rx, ry);
        const glow = ctx.createRadialGradient(0, 0, 0, 0, 0, 1);
        for (const [offset, color] of stops) glow.addColorStop(offset, color);
        ctx.fillStyle = glow;
        ctx.fillRect(-1, -1, 2, 2);
        ctx.restore();
      }

      function stroke(ctx, path, color, width) {
        ctx.strokeStyle = color;
        ctx.lineWidth = width;
        ctx.stroke(path);
      }

      function fill(ctx, path, color) {
        ctx.fillStyle = color;
        ctx.fill(path);
      }

      function curve(points, closed = false) {
        const path = new Path2D();
        path.moveTo(...points[0]);
        for (let i = 0; i < points.length - (closed ? 0 : 1); i++) {
          const a = points[closed ? (i - 1 + points.length) % points.length : Math.max(0, i - 1)];
          const b = points[i];
          const c = points[(i + 1) % points.length];
          const d = points[closed ? (i + 2) % points.length : Math.min(points.length - 1, i + 2)];
          path.bezierCurveTo(
            b[0] + (c[0] - a[0]) / 6, b[1] + (c[1] - a[1]) / 6,
            c[0] - (d[0] - b[0]) / 6, c[1] - (d[1] - b[1]) / 6,
            ...c
          );
        }
        if (closed) path.closePath();
        return path;
      }

      function rounded(points, fraction) {
        const path = new Path2D();
        points.forEach((point, i) => {
          const prev = points[(i - 1 + points.length) % points.length];
          const next = points[(i + 1) % points.length];
          const from = [mix(point[0], prev[0], fraction), mix(point[1], prev[1], fraction)];
          const to = [mix(point[0], next[0], fraction), mix(point[1], next[1], fraction)];
          if (i === 0) path.moveTo(...from);
          else path.lineTo(...from);
          path.quadraticCurveTo(...point, ...to);
        });
        path.closePath();
        return path;
      }

      function thrownEdge(x, y, rx, ry, start = 0, end = tau) {
        const path = new Path2D();
        const steps = Math.ceil((end - start) * 23);
        for (let i = 0; i <= steps; i++) {
          const angle = mix(start, end, i / steps);
          const ruffle = Math.sin(angle * 5 + 1.7) * 0.72 + Math.sin(angle * 9 - 0.4) * 0.41;
          const px = x + Math.cos(angle) * (rx + ruffle);
          const py = y + Math.sin(angle) * (ry + ruffle * 0.55);
          if (i === 0) path.moveTo(px, py);
          else path.lineTo(px, py);
        }
        if (end - start >= tau) path.closePath();
        return path;
      }

      function paintTable(width, height, scale, centerX, centerY) {
        const density = Math.min(1, 1120 / width, 820 / height);
        table.width = Math.max(1, Math.round(width * density));
        table.height = Math.max(1, Math.round(height * density));
        const ctx = table.getContext('2d', { alpha: false });
        const image = ctx.createImageData(table.width, table.height);
        const pixels = image.data;
        const rng = random(1657);

        for (let py = 0; py < table.height; py++) {
          const y = (py / density - centerY) / scale;
          const screenY = py / table.height - 0.49;
          const surface = smooth(-340, 150, y);
          for (let px = 0; px < table.width; px++) {
            const x = (px / density - centerX) / scale;
            const screenX = px / table.width - 0.5;
            const falloff = clamp(1 - 1.18 * screenX ** 2 - 0.97 * screenY ** 2);
            const glow = Math.exp(-((x + 215) / 510) ** 2 - ((y + 106) / 334) ** 2);
            const bounce = Math.exp(-((x + 208) / 484) ** 2 - ((y - 206) / 213) ** 2);
            const clouds = noise(x * 0.009 - 9, y * 0.011) - 0.5;
            const board = y + x * 0.095 + 6 * noise(x * 0.007, y * 0.02);
            const grain = noise(x * 0.013, board * 0.29) - 0.5;
            const fibers = noise(x * 0.036 + 17, board * 0.83) - 0.5;
            const grit = (rng() - 0.5) * 4 + clouds * (2 + 8 * surface)
              + (grain * 5.5 + fibers * 3) * surface;
            const i = 4 * (py * table.width + px);
            pixels[i] = (10 + glow * 34 + bounce * 12 + grit) * falloff + 2;
            pixels[i + 1] = (9 + glow * 20 + bounce * 7 + grit * 0.8) * falloff + 2;
            pixels[i + 2] = (9 + glow * 13 + bounce * 4 + grit * 0.68) * falloff + 2;
            pixels[i + 3] = 255;
          }
        }
        ctx.putImageData(image, 0, 0);
        ctx.setTransform(scale * density, 0, 0, scale * density,
          (centerX - origin.x * scale) * density, (centerY - origin.y * scale) * density);
        blot(ctx, 405, 653, 502, 113, [
          [0, '#c1753e28'], [0.45, '#af56221b'], [0.75, '#8f471012'], [1, '#8f471000']
        ], 0.045);
        blot(ctx, 652, 655, 497, 129, [
          [0, '#080607ed'], [0.49, '#090607c0'], [0.68, '#0a070788'], [1, '#0a070700']
        ], 0.085);
        blot(ctx, 558, 687, 288, 52, [
          [0, '#030203'], [0.62, '#060404d9'], [1, '#06040400']
        ], 0.024);
      }

      const outerLip = thrownEdge(550, 433, 403, 155);
      const innerLip = thrownEdge(550, 434, 386, 142);
      const soup = thrownEdge(liquid.x, liquid.y, liquid.rx, liquid.ry);
      const hull = new Path2D(
        'M147 431 C150 514 210 608 309 655 C377 689 463 702 550 702 ' +
        'C654 702 738 682 802 647 C893 596 943 513 953 431 ' +
        'C932 342 769 279 550 279 C331 279 165 343 147 431Z'
      );

      function paintCeramic(ctx) {
        fill(ctx, oval(551, 681, 188, 27), linear(ctx, 534, 659, 558, 707, [
          [0, '#3d2520'], [0.59, '#1a1211'], [0.85, '#0c0a0a'], [1, '#271814']
        ]));
        const footEdge = new Path2D();
        footEdge.ellipse(550, 680, 186, 27, 0, 0.52, 2.66);
        stroke(ctx, footEdge, linear(ctx, 379, 680, 713, 700, [
          [0, '#67413559'], [0.29, '#92634b68'], [0.62, '#34232038'], [1, '#17111100']
        ]), 1.35);

        fill(ctx, hull, linear(ctx, 416, 486, 488, 705, [
          [0, '#48302a'], [0.36, '#322522'], [0.68, '#1f1716'], [0.92, '#141010'], [1, '#100d0d']
        ]));
        ctx.save();
        ctx.clip(hull);
        blot(ctx, 332, 570, 335, 110, [
          [0, '#a566435c'], [0.36, '#91624443'], [0.7, '#6e413022'], [1, '#6e413000']
        ], 0.24);
        blot(ctx, 529, 616, 308, 80, [
          [0, '#9c583728'], [0.57, '#7942311a'], [1, '#79423100']
        ], 0.025);
        blot(ctx, 866, 555, 152, 110, [
          [0, '#773d2c57'], [0.49, '#5c312842'], [1, '#5c312800']
        ], -0.42);
        fill(ctx, hull, linear(ctx, 360, 540, 860, 669, [
          [0, '#0c080800'], [0.48, '#0a060608'], [0.77, '#08050955'], [1, '#09060895']
        ]));

        const rng = random(450);
        for (let i = 0; i < 104; i++) {
          const t = (i + 1) / 105;
          const cy = 433 + 238 * t;
          const rx = 403 - 220 * Math.pow(t, 1.38);
          const ry = 155 - 125 * t;
          const alpha = 0.013 + rng() * 0.045;
          const path = thrownEdge(550, cy, rx, ry, mix(-0.01, 0.64, rng()), mix(2.84, 3.22, rng()));
          stroke(ctx, path, linear(ctx, 250, cy, 811, cy + 48, [
            [0, 'rgba(236,158,110,' + alpha * 0.84 + ')'],
            [0.31, 'rgba(255,190,144,' + alpha + ')'],
            [0.64, 'rgba(216,135,99,' + alpha * 0.28 + ')'],
            [0.91, 'rgba(213,114,77,' + alpha * 0.56 + ')']
          ]), mix(0.32, 1.2, rng()));
          if (i % 3 === 2) {
            stroke(ctx, thrownEdge(550, cy + 1.25, rx - 1, ry, 0.04, 3.13),
              '#05030439', 0.85);
          }
        }

        for (let i = 0; i < 19000; i++) {
          const x = mix(149, 957, rng());
          const y = mix(467, 706, rng());
          const grain = noise(x * 0.029, y * 0.08);
          const lit = Math.exp(-(((x - 337) / 364) ** 2 + ((y - 576) / 139) ** 2));
          ctx.fillStyle = rng() < 0.45
            ? 'rgba(232,166,116,' + (0.018 + grain * lit * rng() * 0.16) + ')'
            : 'rgba(8,4,5,' + (rng() * 0.29) + ')';
          const length = mix(0.36, 2.8, rng());
          ctx.fillRect(x, y, length, mix(0.35, 1.15, rng()));
        }
        for (let i = 0; i < 45; i++) {
          const x = mix(200, 881, rng());
          const y = mix(532, 699, rng());
          const length = mix(2, 32, rng());
          const slant = clamp((550 - x) / 450, -1, 1) * 0.43;
          const line = new Path2D();
          line.moveTo(x, y);
          line.quadraticCurveTo(x + length * 0.45, y + slant * length * 0.53,
            x + length, y + slant * length);
          stroke(ctx, line, '#b181633a', mix(0.25, 0.63, rng()));
        }
        ctx.restore();

        fill(ctx, outerLip, linear(ctx, 345, 298, 721, 598, [
          [0, '#876451'], [0.17, '#543b31'], [0.42, '#34231f'],
          [0.65, '#6d4938'], [0.84, '#4b322b'], [1, '#2b201e']
        ]));
        stroke(ctx, outerLip, '#130c0b', 1.4);
        fill(ctx, innerLip, linear(ctx, 500, 295, 614, 580, [
          [0, '#1d110e'], [0.13, '#49261a'], [0.34, '#3f251a'],
          [0.66, '#20100c'], [0.92, '#482116'], [1, '#2b170f']
        ]));
        stroke(ctx, innerLip, '#1c110f', 1.7);

        ctx.save();
        ctx.clip(outerLip);
        const ring = new Path2D();
        ring.rect(140, 270, 820, 328);
        ring.addPath(thrownEdge(550, 435, 381, 139));
        ctx.clip(ring, 'evenodd');
        blot(ctx, 294, 325, 340, 68, [
          [0, '#e8bb8c8e'], [0.41, '#d1976663'], [0.75, '#c4884240'], [1, '#c4884200']
        ], -0.27);
        blot(ctx, 434, 572, 283, 48, [
          [0, '#db92645b'], [0.7, '#b3724b38'], [1, '#b3724b00']
        ], 0.08);
        for (let i = 0; i < 4100; i++) {
          const angle = rng() * tau;
          const radius = mix(0.94, 1.008, rng());
          const x = 550 + 403 * radius * Math.cos(angle);
          const y = 433 + 155 * radius * Math.sin(angle);
          ctx.fillStyle = rng() > 0.55 ? '#f2bd8e32' : '#10090766';
          ctx.fillRect(x, y, mix(0.35, 2.2, rng()), mix(0.36, 1, rng()));
        }
        ctx.restore();

        stroke(ctx, thrownEdge(550, 433, 401, 154, 3.08, 6.21),
          linear(ctx, 148, 388, 889, 330, [
            [0, '#6b4e41'], [0.22, '#e1b493b9'], [0.53, '#bd8a70ac'],
            [0.78, '#784d3d80'], [1, '#58362b36']
          ]), 2.15);
        stroke(ctx, thrownEdge(550, 433, 397, 151, 3.19, 5.94), '#21110f9c', 1.12);
        stroke(ctx, thrownEdge(550, 433, 396, 151, 0.14, 3.13),
          linear(ctx, 183, 520, 924, 487, [
            [0, '#99705a3c'], [0.21, '#dda17b9d'], [0.5, '#ca815a5e'],
            [0.77, '#95533b2f'], [1, '#b7714966']
          ]), 1.85);
        stroke(ctx, thrownEdge(550, 433, 402, 155, 0.03, 3.1),
          linear(ctx, 151, 450, 951, 452, [
            [0, '#d6a27f89'], [0.17, '#a0684c72'], [0.54, '#9f624563'], [1, '#ac654d70']
          ]), 1.55);
        stroke(ctx, thrownEdge(550, 435, 390, 144, 0.07, 3.06), '#2e1711aa', 1.46);
        stroke(ctx, thrownEdge(550, 436, 381, 137, 3.04, 6.15),
          linear(ctx, 180, 413, 861, 346, [
            [0, '#a9664482'], [0.28, '#a4765045'], [0.67, '#63392146'], [1, '#96715730']
          ]), 2.3);
      }

      function brothMap() {
        const texture = document.createElement('canvas');
        texture.width = 744;
        texture.height = 268;
        const ctx = texture.getContext('2d');
        const image = ctx.createImageData(texture.width, texture.height);
        const rng = random(24601);
        for (let py = 0; py < texture.height; py++) {
          const y = (py - 134) / 132;
          for (let px = 0; px < texture.width; px++) {
            const x = (px - 372) / 370;
            const i = (py * texture.width + px) * 4;
            const pool = noise(px * 0.016 + 8, py * 0.031);
            const ripple = noise(px * 0.032 + 9 * pool, py * 0.065 + 3.2 * pool);
            const oil = smooth(0.36, 0.69, pool * 0.58 + ripple * 0.42);
            const spice = noise(px * 0.135, py * 0.222);
            const depth = clamp(1 - Math.abs(y + 0.13) * 0.44 - Math.abs(x + 0.09) * 0.12);
            const glow = Math.exp(-(((x + 0.47) * 1.53) ** 2 + ((y - 0.21) * 1.05) ** 2));
            const rim = smooth(0.72, 1.01, x * x + y * y);
            const grit = (rng() - 0.5) * 8 + spice * 7;
            const caustic = (ripple - 0.5) * 16 + (pool - 0.5) * 15;
            pixels[i] = 49 + 87 * depth + 41 * glow + oil * 26 - rim * 27 + caustic + grit;
            pixels[i + 1] = 15 + 42 * depth + 21 * glow + oil * 19 - rim * 14 + caustic * 0.72 + grit;
            pixels[i + 2] = 9 + 13 * depth + 8 * glow + oil * 2 - rim * 5 + caustic * 0.37 + grit * 0.5;
            pixels[i + 3] = 255;
          }
        }
        ctx.putImageData(image, 0, 0);
        return texture;
      }

      function paintBroth(ctx) {
        fill(ctx, soup, '#a45320');
        ctx.save();
        ctx.clip(soup);
        ctx.drawImage(brothMap(), 178, 304);
        const ridge = linear(ctx, 516, 306, 563, 550, [
          [0, '#1c0e0ede'], [0.12, '#2e0e08a0'], [0.3, '#30130c39'],
          [0.68, '#2e110900'], [1, '#a9430e22']
        ]);
        fill(ctx, soup, ridge);
        blot(ctx, 269, 454, 148, 66, [
          [0, '#ffab4e76'], [0.55, '#e9964139'], [1, '#e8872800']
        ], -0.06);
        blot(ctx, 522, 550, 277, 54, [
          [0, '#ef8a2c47'], [0.68, '#d16c242d'], [1, '#d16c2400']
        ], 0.033);
        blot(ctx, 843, 479, 84, 54, [
          [0, '#f096483f'], [0.64, '#d0753030'], [1, '#d0753000']
        ], -0.18);

        const rng = random(210299);
        for (let i = 0; i < 460; i++) {
          const angle = rng() * tau;
          const distance = Math.sqrt(rng()) * 0.986;
          const x = 550 + Math.cos(angle) * 368 * distance;
          const y = 437 + Math.sin(angle) * 132 * distance;
          const size = 0.65 + Math.pow(rng(), 3.35) * 21;
          const height = size * mix(0.25, 0.55, rng()) + 0.23;
          const shade = rng();
          const lit = clamp(1.16 - (x - 190) / 1040 + (y - 425) / 268);
          const outline = thrownEdge(x, y, size, height);
          fill(ctx, outline, linear(ctx, x - size * 0.38, y - height, x + size * 0.2, y + height, [
            [0, shade > 0.53 ? '#e388323e' : '#85311b4a'],
            [0.47, shade > 0.53 ? '#b7502040' : '#a7381638'],
            [1, shade > 0.53 ? '#6828135c' : '#ce682c4c']
          ]));
          if (size > 1.5) stroke(ctx, outline, 'rgba(98,35,15,' + lit * 0.3 + ')', 0.7);
          const gleam = new Path2D();
          gleam.ellipse(x, y, size * 0.84, height * 0.86, -0.025, 3.47, mix(4.26, 5.51, rng()));
          stroke(ctx, gleam, 'rgba(255,192,106,' + lit * mix(0.18, 0.49, rng()) + ')',
            mix(0.38, 0.91, rng()));
        }

        for (let i = 0; i < 1350; i++) {
          const x = mix(178, 920, rng());
          const y = mix(317, 569, rng());
          const coarse = rng() ** 5;
          ctx.fillStyle = rng() < 0.64 ? '#42190c45' : '#ffc5753b';
          ctx.fillRect(x, y, 0.45 + coarse * 2.95, 0.36 + coarse * 1.4);
        }
        stroke(ctx, thrownEdge(550, 438, 367, 130, 0.1, 3.12),
          linear(ctx, 197, 477, 899, 491, [
            [0, '#ffad6065'], [0.24, '#ffd38a77'], [0.49, '#ffa6543d'], [1, '#d671353e']
          ]), 2.15);
        stroke(ctx, thrownEdge(550, 438, 365, 128, 3.02, 6.3), '#3e1b135e', 2.9);
