text(await tools.exec_command({cmd:String.raw`cat >> /app/index.html <<'EOF'

      const greens = [
        ['#1d351c', '#3b5725', '#627c32', '#304719'],
        ['#24391c', '#4c6b2a', '#849844', '#365720'],
        ['#24381a', '#45742a', '#718f38', '#2e4f22'],
        ['#172d16', '#375e23', '#79953c', '#304e1c']
      ];

      function bokChoy(ctx, base, control, tip, spread, colors, seed) {
        const rng = random(seed);
        const phase = rng() * tau;
        function frame(t) {
          const s = 1 - t;
          const x = s * s * base[0] + 2 * s * t * control[0] + t * t * tip[0];
          const y = s * s * base[1] + 2 * s * t * control[1] + t * t * tip[1];
          const dx = s * (control[0] - base[0]) + t * (tip[0] - control[0]);
          const dy = s * (control[1] - base[1]) + t * (tip[1] - control[1]);
          const length = Math.hypot(dx, dy);
          return { x, y, nx: -dy / length, ny: dx / length };
