  '--disable-background-networking', '--no-first-run', '--remote-debugging-port=0',
  '--user-data-dir=' + profile, 'about:blank'], { stdio: 'ignore' });

let exitCode = 0;
try {
  let port;
  for (let i = 0; i < 120 && !port; i++) {
    await delay(50);
    port = (await readFile(profile + '/DevToolsActivePort', 'utf8').catch(() => '')).split('\n')[0];
  }
  if (!port) throw new Error('Chromium did not start');
  const targets = await fetch('http://<LAN_IP>:' + port + '/json/list').then(response => response.json());
  const ws = new WebSocket(targets.find(target => target.type === 'page').webSocketDebuggerUrl);
  const pending = new Map();
  const errors = [];
  const requests = [];
  let id = 0;
  ws.addEventListener('message', event => {
    const msg = JSON.parse(event.data);
    if (msg.id) {
      const { resolve, reject } = pending.get(msg.id);
      pending.delete(msg.id);
      if (msg.error) reject(new Error(JSON.stringify(msg.error)));
      else resolve(msg.result);
    } else if (msg.method === 'Runtime.exceptionThrown') {
      const info = msg.params.exceptionDetails;
      errors.push(info.exception?.description || info.text);
    } else if (msg.method === 'Network.requestWillBeSent') {
      requests.push(msg.params.request.url);
    }
  });
  await new Promise((resolve, reject) => {
    ws.addEventListener('open', resolve, { once: true });
    ws.addEventListener('error', reject, { once: true });
  });
  const call = (method, params = {}) => new Promise((resolve, reject) => {
    const callId = ++id;
    pending.set(callId, { resolve, reject });
    ws.send(JSON.stringify({ id: callId, method, params }));
  });
  const evaluate = async expression => {
    const obj = await call('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
    if (obj.exceptionDetails) throw new Error(obj.exceptionDetails.exception?.description);
    return obj.result.value;
  };
  const metrics = (width, height, mobile = false, deviceScaleFactor = 1) =>
    call('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor, mobile });
  const reduced = (preference = true) => call('Emulation.setEmulatedMedia',
    { features: [{ name: 'prefers-reduced-motion', value: preference ? 'reduce' : 'no-preference' }] });
  const shot = async path => {
    const { data } = await call('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
    await writeFile(path, Buffer.from(data, 'base64'));
  };

  await Promise.all([call('Runtime.enable'), call('Network.enable'), call('Page.enable')]);
  await metrics(1440, 900);
  await reduced();
  await call('Page.navigate', { url: 'file:///app/index.html' });
  await delay(800);
  await shot('<TMP>/ramen-desktop.png');
  console.log('errors', JSON.stringify(errors));
  console.log('requests', JSON.stringify(requests));
  console.log('canvas sizes', await evaluate("[...document.querySelectorAll('canvas')].map(c => [c.width,c.height,c.clientWidth,c.clientHeight])"));

  await metrics(390, 844, true);
  await delay(450);
  await shot('<TMP>/ramen-mobile.png');

  if (process.argv.includes('--behavior')) {
    const vapor = "document.querySelector('.steam').toDataURL()";
    const pot = "document.querySelector('.dish').style.transform";
    const initial = await evaluate(vapor);
    await call('Input.dispatchMouseEvent', { type: 'mouseMoved', x: 365, y: 560 });
    await delay(425);
    const reducedStill = initial === await evaluate(vapor);
    const reducedPosition = await evaluate(pot);
    await metrics(1440, 900);
    await reduced(false);
    await delay(500);
    const beforeMotion = await evaluate(vapor);
    await call('Input.dispatchMouseEvent', { type: 'mouseMoved', x: 1345, y: 640 });
    await delay(650);
    const motionChanged = beforeMotion !== await evaluate(vapor);
    const moved = await evaluate(pot);
    await shot('<TMP>/ramen-active.png');
    await reduced();
    await delay(300);
    const frozen = await evaluate(vapor);
    await delay(400);
    const stops = frozen === await evaluate(vapor);
    console.log({ reducedStill, reducedPosition, motionChanged, moved, stops, errors, requests });
    if (!reducedStill || !motionChanged || !stops || errors.length || moved === reducedPosition) exitCode = 1;
  }
  ws.close();
} finally {
  browser.kill();
  await delay(225);
  await rm(profile, { force: true, recursive: true });
}
process.exitCode = exitCode;
EOF
